class Report {
  private debugLines: string[] = [];

  addLine(line: string) {
    this.debugLines.push(line);
  }

  generate() {
    if (this.debugLines.length === 0) return "empty";
    const output = this.debugLines.join("\n");
    return output;
  }
}

